208		atStr := fs.String("at", "", "query time (RFC3339); default: now")
209		expectedVersion := fs.String("expected-version", "", "expected version (required)")
210		toleratedMisses := fs.Int("tolerated-misses", -1, "tolerated missed duties, >= 0 (required)")
211		missedSinceSeq := fs.Int64("missed-since-seq", 0, "seq of a saved heartbeat to use as the missed-duty baseline; must be > 0 and exist for the node")
212		if err := fs.Parse(args); err != nil {
213			if err == flag.ErrHelp {
214				os.Exit(0)
215			}
216			os.Exit(2)
217		}
218		if *node == "" {
219			die("--node is required")
220		}
221		if *expectedVersion == "" {
222			die("--expected-version is required")
223		}
224		if *toleratedMisses < 0 {
225			die("--tolerated-misses is required and must be >= 0")
226		}
227		if isFlagPassed(fs, "missed-since-seq") && *missedSinceSeq <= 0 {
228			die("--missed-since-seq must be a positive integer")
229		}
230	
231		at := parseTimeFlag(*atStr, "--at")
232	
233		store, err := edgefleet.OpenStore(*dataDir)
234		if err != nil {
235			die("%v", err)
236		}
237	
238		var result edgefleet.HealthResult
239		if isFlagPassed(fs, "missed-since-seq") {
240			result, err = store.HealthSince(*node, at, *expectedVersion, *toleratedMisses, *missedSinceSeq)
241		} else {
242			result, err = store.Health(*node, at, *expectedVersion, *toleratedMisses)
243		}
244		if err != nil {
245			die("%v", err)
246		}
247	
248		// Node id and version go through the shared display rule: text that would
249		// break the one-line format (newlines, tabs, quotes, backslashes, control
250		// characters) is shown as a quoted JSON string, so a health query always
251		// prints exactly one line — two with a missed-duty baseline — and node
252		// text can never masquerade as extra fields or a second result line.
253		if result.Status == "notelemetry" {
254			fmt.Printf("node=%s status=无遥测 findings=[无遥测]\n", edgefleet.DisplayText(result.NodeID))
255			return
256		}
257		fmt.Printf("node=%s status=%s seq=%d collected_at=%s version=%s height=%d missed=%d findings=%v\n",
258			edgefleet.DisplayText(result.NodeID), result.Status, result.Seq, result.CollectedAt.Format(time.RFC3339),
259			edgefleet.DisplayText(result.Version), result.Height, result.Missed, result.Findings)
260		if isFlagPassed(fs, "missed-since-seq") {
261			// missed above stays cumulative; this line states the alarm basis.
262			if result.NewMissedKnown {
263				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=%d tolerated_misses=%d\n",
264					result.BaselineSeq, result.BaselineMissed, result.NewMissed, *toleratedMisses)
265			} else {
266				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=无法判断 tolerated_misses=%d\n",
267					result.BaselineSeq, result.BaselineMissed, *toleratedMisses)
268			}
269		}
270	}
271	
272	// isFlagPassed reports whether the named flag was explicitly set on the
273	// command line, so an optional flag with a zero default can be distinguished
274	// from its absence.
275	func isFlagPassed(fs *flag.FlagSet, name string) bool {
276		passed := false
277		fs.Visit(func(f *flag.Flag) {
278			if f.Name == name {
279				passed = true
280			}
281		})
282		return passed
283	}
284	
285	func cmdHistory(args []string) {
286		fs := newFlagSet("heartbeat history")
287		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
288		node := fs.String("node", "", "node id (required)")
289		if err := fs.Parse(args); err != nil {
290			if err == flag.ErrHelp {
291				os.Exit(0)
292			}
293			os.Exit(2)
294		}
295		if *node == "" {
296			die("--node is required")
297		}
298	
299		store, err := edgefleet.OpenStore(*dataDir)
300		if err != nil {
301			die("%v", err)
302		}
303		records, err := store.History(*node)
304		if err != nil {
305			die("%v", err)
306		}
307		if len(records) == 0 {
308			fmt.Printf("node=%s no heartbeats\n", *node)
309			return
310		}
311		for _, r := range records {
312			fmt.Printf("node=%s seq=%d collected_at=%s version=%s height=%d missed=%d\n",
313				r.NodeID, r.Seq, r.CollectedAt.Format(time.RFC3339), r.Version, r.Height, r.Missed)
314		}
315	}
316	
317	func runDemo() {
318		nodes := []edgefleet.Node{
319			{ID: "val-eu-1", Region: "eu", Version: "1.26.0", Online: true},
320			{ID: "val-us-1", Region: "us", Version: "1.25.4", Online: true, Missed: 3},
321			{ID: "edge-ap-1", Region: "ap", Version: "1.26.0", Online: false},
322		}
323		unhealthy := 0
324		for _, node := range nodes {
325			health := edgefleet.Evaluate(node, "1.26.0", 1)
326			if !health.Healthy {
327				unhealthy++
328			}
329			fmt.Printf("node=%s healthy=%v findings=%v\n", health.Node, health.Healthy, health.Findings)
330		}
331		fmt.Println("rollout order:", edgefleet.Plan(nodes, "1.26.0"))
332		fmt.Printf("summary: %d of %d nodes need attention\n", unhealthy, len(nodes))
333	}
