		{"missing version",
			`{"node":"ok","seq":2,"collected_at":"2026-10-01T11:59:59Z","height":8,"missed":0}`, "version"},
		{"missing height",
			`{"node":"ok","seq":2,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","missed":0}`, "height"},
