110	
111	// checkCollectedAtValue holds the single set of rules a collection instant
112	// must satisfy at every trust boundary. Beyond being present (not the zero
113	// time), the instant must be losslessly representable in the on-disk format:
114	// a four-digit year (0000..9999, the only years RFC3339Nano writes) and a
115	// zone offset the minute-granular RFC3339 text can keep exactly — whole
116	// minutes and no larger in magnitude than 23:59. A seconds-bearing offset
117	// (possible only on the direct Go submit entry) would otherwise be saved as
118	// a different instant, and an out-of-range year or offset only fails at
119	// marshal time, after other nodes in the batch were already written.
120	func checkCollectedAtValue(collected time.Time) *fieldValueError {
121		if collected.IsZero() {
122			return &fieldValueError{field: "collected_at", issue: issueMissingInstant}
123		}
124		year := collected.Year()
125		if year < 0 || year > 9999 {
126			return &fieldValueError{field: "collected_at", issue: issueYearOutOfRange, value: int64(year)}
127		}
128		_, offset := collected.Zone()
129		if offset < -maxZoneOffsetSeconds || offset > maxZoneOffsetSeconds {
130			return &fieldValueError{field: "collected_at", issue: issueOffsetOutOfRange, value: int64(offset)}
131		}
132		if offset%60 != 0 {
133			return &fieldValueError{field: "collected_at", issue: issueOffsetSeconds, value: int64(offset)}
134		}
135		return nil
136	}
137	
138	// maxZoneOffsetSeconds is the largest zone offset magnitude accepted in a
139	// collected_at value: 23 hours 59 minutes. Hours 00..23 and minutes 00..59
140	// are exactly the fields the RFC3339 suffix carries; +24:00 and -24:00 are
141	// out of range, and +00:60 is not folded into +01:00.
142	const maxZoneOffsetSeconds = 23*3600 + 59*60
143	
144	// checkHeartbeatValues runs every context-free field-value rule in the single
145	// rejection order shared by the direct-submit and stored-data boundaries:
146	// node, seq, version, height, missed, then collected_at. It deliberately does
147	// NOT compare against a receive time: reading saved history has no receive
148	// time, and that submit-only rule lives in checkCollectedAtTiming.
149	func checkHeartbeatValues(h Heartbeat) *fieldValueError {
150		if e := checkNodeIDValue(h.NodeID); e != nil {
151			return e
152		}
153		if e := checkPositiveInt("seq", h.Seq); e != nil {
154			return e
155		}
156		if e := checkVersionValue(h.Version); e != nil {
157			return e
158		}
159		if e := checkNonNegativeInt("height", h.Height); e != nil {
160			return e
161		}
162		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
163			return e
164		}
165		return checkCollectedAtValue(h.CollectedAt)
166	}
167	
168	// checkCollectedAtTiming holds the single receive-time rule, which belongs to
169	// submission only: a collection time later than the receive time is refused;
170	// the same instant expressed in another timezone is equal and allowed. The
171	// stored-data read path never calls this, so reading history introduces no
172	// current time and no extra time limit.
173	func checkCollectedAtTiming(collected, receiveTime time.Time) error {
174		if collected.After(receiveTime) {
175			return fmt.Errorf("collected_at %s is later than receive time %s",
176				collected.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
177		}
178		return nil
179	}
180	
181	// formatZoneOffset renders an offset in seconds as the RFC3339 suffix shape
182	// +HH:MM, or +HH:MM:SS when the offset carries seconds. Hours are not rolled
183	// over (an out-of-range +24:00 is shown as +24:00), so the message shows
184	// exactly the offset the caller supplied.
185	func formatZoneOffset(sec int64) string {
186		sign := '+'
187		if sec < 0 {
188			sign = '-'
189			sec = -sec
190		}
191		h := sec / 3600
192		m := sec % 3600 / 60
193		if s := sec % 60; s != 0 {
